import re

def extract_solidity_code(response: str):
    """Extract Solidity code from LLM response"""
    # Remove <think> ... </think> blocks
    code_block = re.sub(r"<think>[\s\S]*?</think>", "", response).strip()
    
    # Extract content between ```solidity ... ```
    # Two-pass: first capture ```solidity:xxx or ```solidity <filename> (non-empty tail), then bare ```solidity
    solidity_matches = re.findall(r"```[ \t]*solidity(?::[^\n]*|[ \t]+[^\n]+)\n([\s\S]*?)```", code_block, re.MULTILINE | re.IGNORECASE)
    if not solidity_matches:
        solidity_matches = re.findall(r"```[ \t]*solidity[ \t]*\n([\s\S]*?)```", code_block, re.MULTILINE | re.IGNORECASE)
    if solidity_matches:
        code_block = solidity_matches[-1].strip()
        return code_block, True
    
    # Try generic code blocks
    code_matches = re.findall(r"```[^\n]*\n([\s\S]*?)```", code_block, re.MULTILINE)
    if code_matches:
        return code_matches[-1].strip(), True
    
    return code_block, False

import json

def try_extract_from_json1(response: str):
    # More robust approach: after a ```json fence locate the first JSON start
    # character ([ or {) and use json.JSONDecoder.raw_decode from that position
    # (raw_decode returns the consumed length). This lets the stdlib handle
    # string escapes and boundary detection and avoids corner cases of manual
    # bracket-matching logic.
    fence = '```json'
    decoder = json.JSONDecoder()
    for m in re.finditer(re.escape(fence), response, flags=re.IGNORECASE):
        pos = m.end()
        # Skip whitespace
        i = pos
        while i < len(response) and response[i] in ' \t\r\n':
            i += 1
        if i >= len(response):
            continue
        # Find the first possible JSON start character
        j1 = response.find('[', i)
        j2 = response.find('{', i)
        starts = [x for x in (j1, j2) if x != -1]
        if not starts:
            continue
        start = min(starts)
        try:
            obj, consumed = decoder.raw_decode(response[start:])
        except Exception:
            # raw_decode failed to parse, skip this fence
            continue

        # raw_decode returns (obj, consumed); at this point we have a complete JSON
        def find_content(obj):
            if isinstance(obj, dict):
                for k, v in obj.items():
                    if k == 'content' and isinstance(v, str):
                        return v
                    res = find_content(v)
                    if res:
                        return res
            elif isinstance(obj, list):
                for item in obj:
                    res = find_content(item)
                    if res:
                        return res
            return None

        content = find_content(obj)
        if content:
            return content
        # If no 'content' found, return the parsed JSON text as a fallback
        try:
            return json.dumps(obj)
        except Exception:
            return response

    # Return None when no JSON block or 'content' field is found (caller should
    # perform a fallback extraction)
    return None

def try_extract_from_json(response: str):
    """Simple strategy: find the first ``` and the last ```, extract JSON between them"""
    
    # Find all ``` positions
    fence_positions = [m.start() for m in re.finditer(r'```', response)]
    
    if len(fence_positions) < 2:
        return None
    
    # Content after the first ``` (skip possible json marker)
    first_fence = fence_positions[0]
    start_pos = response.find('\n', first_fence) + 1
    
    # Content before the last ```
    last_fence = fence_positions[-1]
    
    json_str = response[start_pos:last_fence].strip()
    
    # Try to fix JSON escaping issues
    # 1. Replace actual newlines with \n
    # 2. Replace actual tabs with \t
    # 3. Ensure quotes are properly escaped
    
    # Simple approach: if json.loads fails, try fallback methods
    try:
        obj = json.loads(json_str)
    except json.JSONDecodeError:
        try:
            # Try to fix common newline issues
            # Note: We assume newlines are the main cause of JSON parse failures
            # In JSON string values, newlines must be escaped as \n
            # However, if JSON itself is formatted (multi-line), we can't simply replace all newlines
            # This is a dilemma.
            # Let's try a heuristic approach:
            # If we see "content": "..." structure with newlines in the value, that might be the issue.
            
            # Alternative: use regex to extract the content field value
            # Find "content": "..." pattern, handling escaped quotes
            content_match = re.search(r'"content"\s*:\s*"(.*?)"(?=\s*[},])', json_str, re.DOTALL)
            if content_match:
                # Extracted content may contain escape sequences, we need to unescape
                raw_content = content_match.group(1)
                # Manually handle unescaping: \\n -> \n, \\" -> "
                # Note: there may be other escape sequences
                return raw_content.replace('\\n', '\n').replace('\\"', '"').replace('\\\\', '\\')
            
            return None
        except Exception:
             return None
                    
    except json.JSONDecodeError:
        pass
    
    return None

def try_extract_code(response: str) -> str:
    """Try to extract Solidity code from JSON or directly from response"""
    # First try to extract from JSON
    content = try_extract_from_json(response)
    if not content:
        content = try_extract_from_json1(response)
    if content:
        code, _ok = extract_solidity_code(content)
        return code
    # If no JSON, extract directly
    code, _ok = extract_solidity_code(response)
    return code

